import os
import torch


class Config:
    """
    Configuration class for the GPU-Accelerated Sparse Linear Network pipeline.
    Acts as the single source of truth for all hyperparameters and paths.
    """

    # ---------------------------------------------------------
    # 1. File Paths & Directories
    # ---------------------------------------------------------
    # Input Metadata (Generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_PATH = os.path.join(METADATA_DIR, "validation.csv")
    TEST_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Working Directory for Artifacts (Cache, Models, Vectorizers)
    WORKING_DIR = "./working/idea_5"

    # Submission Directory
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ---------------------------------------------------------
    # 2. Data Processing Hyperparameters
    # ---------------------------------------------------------
    # TF-IDF Vectorization
    VOCAB_SIZE = 150000  # Number of features (Unigrams + Bigrams)
    NGRAM_RANGE = (1, 2)  # Capture local context via bigrams
    MIN_DF = 2  # Ignore terms that appear in less than 2 docs
    MAX_DF = 0.95  # Ignore terms that appear in > 95% of docs

    # Target Encoding
    NUM_TAGS = 5000  # Number of most frequent tags to predict

    # Debugging / Development
    DEBUG = False  # Set to True to use a smaller subset for testing
    DEBUG_SIZE = 100000  # Number of samples to use in debug mode

    # ---------------------------------------------------------
    # 3. Model Hyperparameters
    # ---------------------------------------------------------
    INPUT_DIM = VOCAB_SIZE
    OUTPUT_DIM = NUM_TAGS

    # ---------------------------------------------------------
    # 4. Training Hyperparameters
    # ---------------------------------------------------------
    SEED = 42
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    EPOCHS = 10
    BATCH_SIZE = 4096  # Large batch size to maximize GPU throughput
    LEARNING_RATE = 1e-3  # Adam learning rate
    WEIGHT_DECAY = 1e-5  # L2 Regularization

    NUM_WORKERS = 4  # Number of subprocesses for data loading

    # Early Stopping
    PATIENCE = 3  # Epochs to wait before stopping if no improvement
    MIN_DELTA = 1e-4  # Minimum change to qualify as an improvement

    # ---------------------------------------------------------
    # 5. Loss Function (Focal Loss)
    # ---------------------------------------------------------
    # Addresses extreme class imbalance in sparse multi-label data
    FOCAL_ALPHA = 0.25  # Weighting factor for positive/negative classes
    FOCAL_GAMMA = 2.0  # Focusing parameter for hard examples

    # ---------------------------------------------------------
    # 6. Inference & Thresholding
    # ---------------------------------------------------------
    # Distribution-Aware Threshold Tuning
    # We search for the optimal threshold based on percentiles of predicted probabilities
    THRESHOLD_SEARCH_START = 95.0
    THRESHOLD_SEARCH_END = 99.9
    THRESHOLD_SEARCH_STEPS = 50


# ---------------------------------------------------------
# Automatic Setup
# ---------------------------------------------------------
# Ensure necessary directories exist when config is imported
os.makedirs(Config.WORKING_DIR, exist_ok=True)
os.makedirs(Config.SUBMISSION_DIR, exist_ok=True)
